    console.assert(JSON.stringify(candidate([256, 128, 64, 32, 16, 8, 4, 2, 1, 2, 4, 8, 16, 32, 64, 128, 256])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([8, 15, 17, 4, 3, 10, 12, 7, 6, 9, 11, 5, 2, 14, 13, 1, 0, 16, 32, 64, 128, 256])) === JSON.stringify(45));
    console.assert(JSON.stringify(candidate([2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768])) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate([5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55, 60, 65, 70, 75])) === JSON.stringify(5));
